css:
.Btn-container {
  width: fit-content;
  height: fit-content;
  border: none;
  background-color: #ebebeb;
  padding: 10px;
  border-radius: 10px;
  box-shadow: 0px 2px 5px #e1e1e1;
  transition: 0.2s;
}
.inner-wrapper {
  width: fit-content;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f7f7f7;
  border-radius: 5px;
  padding: 8px 15px;
  box-shadow: 0px 4px 10px #d3d3d3;
  gap: 50px;
  transition: 0.2s;
}
.text {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.text p {
  font-size: 1.2em;
  font-weight: 600;
  color: rgb(140, 140, 140);
}
.text .pro {
  background-color: black;
  color: white;
  padding: 4px 8px;
  border-radius: 5px;
}
.icon {
  width: 40px;
  height: 40px;
  background-color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transform: rotate(45deg);
  transition: 0.2s;
}
.icon svg {
  width: 15px;
}
.Btn-container:active {
  transform: scale(1);
}
.Btn-container:active .inner-wrapper {
  transform: scale(0.97);
}
.Btn-container:hover .icon {
  transform: rotate(0deg);
}
